// Read-only product audit: mutations run only in the in-memory Page/WXML runtime.
const fs=require('fs'),path=require('path'),assert=require('assert/strict');
const out=path.resolve('qa/engineering-finance-audit-20261021');
const copy=x=>JSON.parse(JSON.stringify(x));
(async()=>{
 const runtime=await require('./role-page-runtime.cjs').connect();
 const A=require('../miniprogram/utils/account'),B=require('../miniprogram/utils/business'),E=require('../miniprogram/pages/build/model'),M=require('../miniprogram/pages/admin/model'),Ops=require('../miniprogram/utils/operations'),X=require('../miniprogram/utils/access'),W=require('../miniprogram/pages/build/workbench'),Vis=require('../miniprogram/utils/page-visibility');
 const trace=JSON.parse(fs.readFileSync(path.join(out,'main-trace.json'),'utf8')).steps;
 const scene=(area,action)=>trace.find(s=>s.area===area&&(s.action===action||new URL(s.url,'http://local').searchParams.get('view')===action));
 const install=rows=>{wx.getStorageInfoSync().keys.forEach(k=>wx.removeStorageSync(k));for(const[k,v]of copy(rows))wx.setStorageSync(k,v);};
 const login=(id,role)=>{A.mutate(a=>A.loginDemo(a,id));if(role)A.mutate(a=>A.switchIdentity(a,a.session.companyId,role));};
 const open=url=>{wx.reLaunch({url});return getCurrentPages().at(-1);};
 const navigationOnly=process.argv.includes("--navigation-only");const results=[];const check=(name,fn)=>{if(navigationOnly)return;try{const evidence=fn();results.push({name,result:'observed',evidence});console.log('OBSERVED '+name);}catch(e){results.push({name,result:'probe-error',error:e.stack});console.error('PROBE ERROR '+name+' '+e.message);}};
 const base=scene('build','deliver'),eid=new URL(base.url,'http://local').searchParams.get('id'),pid=Object.fromEntries(base.before)[E.KEY].projects.find(p=>p.id===eid).projectId;
 const mutateProject=fn=>{const s=wx.getStorageSync(E.KEY);fn(s.projects.find(p=>p.id===eid));wx.setStorageSync(E.KEY,s);};
 const stripReceipts=()=>{const s=wx.getStorageSync(M.KEY);for(const b of [s,...Object.values(s.books||{})]){b.receipts=[];if(b.operations)b.operations.plans=[];}wx.setStorageSync(M.KEY,s);mutateProject(p=>p.collections=[]);};
 check('F01 未配置付款期次且工程实收为零仍允许交付及归档',()=>{install(base.before);stripReceipts();const book=M.load(),gate=Ops.gate(book,pid,'delivery');assert.equal(Ops.actual(book,pid),0);assert.equal(gate.allowed,true);assert.equal(gate.configured,false);E.apply(eid,'deliver',base.form);E.apply(eid,'archive');return {contract:Ops.contract(Ops.project(pid,book)).total,received:0,gate,archived:E.get(eid).archived};});
 check('F02 工程负责人可读团队工程但不能代办本团队项目',()=>{install(base.before);login('engineering-lead','project-manager');const p=E.get(eid);assert(p);assert(X.engineeringTeam(p));const readable=true,visible=Vis.engineering(p,'site');let error='';try{E.apply(eid,'site',{date:A.localDate(),note:'负责人代办检查',file:{name:'audit.pdf',sample:true}},{nodeId:p.plan.nodes[0].id});}catch(e){error=e.message;}assert.equal(visible,false);assert(error);return {readable,staffId:X.context().staffId,managerId:X.managerId(p),team:X.context().managedTeamIds,error};});
 for(const [view,action,form]of [
  ['supply-promise','supply-promise',{date:A.localDate(),note:'重新协调原承诺',checked:true,file:{name:'promise.pdf',sample:true}}],
  ['material-usage','material-use',{kind:'领用耗用',quantity:'1',date:A.localDate(),person:'现场经办',note:'节点使用',file:{name:'usage.pdf',sample:true}}],
  ['stock','depot-use',{stock:'不应静默忽略的输入',quantity:'1',date:A.localDate(),person:'现场经办',note:'余料领用',file:{name:'stock.pdf',sample:true}}]
 ])check('F03 主按钮未分发动作 '+action,()=>{install(base.before);let p=E.get(eid),s=p.supplies[0];const url='/pages/build/index?view='+view+'&id='+eid+'&supplyId='+s.id+'&materialId='+s.materialId;const page=open(url);assert.equal(page.data.action,action);assert(page.data.primary);page.setData({form:{...page.data.form,...form}});const before=JSON.stringify(wx.getStorageSync(E.KEY));page.primary();const after=JSON.stringify(wx.getStorageSync(E.KEY));assert.equal(before,after);assert.equal(page.data.error,'');return {view,action,primary:page.data.primary,unchanged:true,error:page.data.error};});
 check('F04 独立新增工程的专业送审角色无法匹配',()=>{install(base.before);const p=E.add({name:'审计独立项目',customer:'审计客户',city:'武汉市',area:'360',floors:'2',drawingFile:{name:'施工图.pdf',sample:true}});const page=open('/pages/build/index?view=review&id='+p.id);assert.equal(page.data.action,'review-request');assert(page.data.primary);page.primary();assert(page.data.error.includes('设计师'));return {project:p.id,role:X.context().role,primary:page.data.primary,error:page.data.error,ready:E.ready(E.get(p.id))};});
 check('F05 普通工程身份首页显示需要切换负责人的接收待办',()=>{const s=scene('workflow','receive');install(s.before);login('engineering-dual','engineer');const tasks=W.snapshot().tasks.filter(t=>t.id.startsWith('handover:'));assert(tasks.length);const page=open(tasks[0].url);page.setData({form:{...page.data.form,...s.form}});page.submit();assert(page.data.error.includes('工程负责人'));return {task:tasks[0],role:X.context().role,error:page.data.error};});
 check('F06 工程归档不代表财务结清且不存在独立财务关账状态',()=>{install(base.after);mutateProject(p=>{p.archived=true;p.collections=[];p.payments=[];});stripReceipts();login('finance-dual','finance-lead');const s=M.load(),row=Ops.overview(s).rows.find(r=>r.id===pid);assert(row&&row.remaining>0);return {stage:row.stage,contract:row.total,received:row.received,remaining:row.remaining,costComplete:row.cost.complete,payable:Ops.overview(s).payable,projectFields:Object.keys(E.get(eid)||{})};});
 check('F07 材料收货允许早于项目接收日期',()=>{const s=scene('build','receive');install(s.before);const q=new URL(s.url,'http://local'),ctx=Object.fromEntries(q.searchParams);const before=E.get(eid);E.apply(eid,'receive',{...s.form,date:'2000-01-01'},ctx);return {accepted:before.accepted,receivedDate:E.get(eid).receipts.at(-1).date};});
 check('F08 供应付款约定在实际付款前可改写导致老板批准版本失效待核',()=>{const s=scene('admin','pay');install(scene('build','receive').before);const p=E.get(eid),supply=p.supplies[0];mutateProject(p=>p.payments=[]);const book=wx.getStorageSync(M.KEY);for(const b of [book,...Object.values(book.books||{})])b.payments=(b.payments||[]).filter(p=>p.source?.supplyId!==supply.id&&!String(p.payableId).includes(supply.id));wx.setStorageSync(M.KEY,book);let error='';try{E.apply(eid,'supply-complete',{payer:supply.payer,unitPrice:String(supply.unitPrice+1),basis:{name:'new-basis.pdf',sample:true}},{supplyId:supply.id});}catch(e){error=e.message;}return {oldUnit:supply.unitPrice,newUnit:E.get(eid).supplies[0].unitPrice,error,note:'用于核对审批版本是否自动判旧，不能单凭可编辑认定缺陷'};});
 // Audit every rendered navigation control on representative engineering states.
 const nav=[];const flat=nodes=>nodes.flatMap(n=>[n,...flat(n.children||[])]),render=require('./role-page-runtime.cjs').render;
 const V=require('../miniprogram/pages/build/views');
 for(const stage of ['start','receive','deliver']){
  const s=scene('build',stage);
  for(const view of Object.keys(V.titles).filter(v=>!['new','boss','projects','customer'].includes(v))){
   install(s.before);const project=E.get(eid);if(!project)continue;const supply=project.supplies[0],receipt=project.receipts[0],inspection=project.inspections[0],reship=project.reships[0];
   const query={nodeId:project.plan.nodes.find(n=>n.status!=='已完成')?.id||project.plan.nodes[0].id,...(supply?{supplyId:supply.id,materialId:supply.materialId}:{}),...(receipt?{receiptId:receipt.id}:{}),...(inspection?{inspectionId:inspection.id}:{}),...(reship?{reshipId:reship.id}:{})};
   const url='/pages/build/index?view='+view+'&id='+eid+Object.entries(query).map(([k,v])=>'&'+k+'='+v).join('');
   let page;try{page=open(url);}catch(e){nav.push({stage,view,result:'open-error',error:e.message});continue;}
   if(page.data.missing){nav.push({stage,view,result:'blocked',error:page.data.error});continue;}
   let nodes;try{nodes=flat(render(page.file,page.data)).filter(n=>['go','openOperating','taskAccess','tab'].includes(n.attrs?.bindtap));}catch(e){nav.push({stage,view,result:'render-error',error:e.message});continue;}
   for(const n of nodes){install(s.before);page=open(url);const dataset=Object.fromEntries(Object.entries(n.attrs).filter(([k])=>k.startsWith('data-')).map(([k,v])=>[k.slice(5).replace(/-([a-z])/g,(_,x)=>x.toUpperCase()),v]));const handler=n.attrs.bindtap;try{page[handler]({currentTarget:{dataset},target:{dataset}});const p=getCurrentPages().at(-1);nav.push({stage,view,handler,target:dataset.view||dataset.index||'',result:p.data.missing||p.data.error||p.data.view==='access'?'target-blocked':'opened',route:p.route,next:p.data.view,error:p.data.error||'',modal:p.data.modal||''});}catch(e){nav.push({stage,view,handler,target:dataset.view||dataset.index||'',result:'error',error:e.message});}}
  }
 }
 fs.writeFileSync(path.join(out,navigationOnly?'navigation-fixed.json':'probes.json'),JSON.stringify({scope:'当前代码真实 Page 处理器、WXML 和模型；仅内存测试，无微信渲染结论',date:'2026-10-21',results,navigation:nav},null,2));
 if(nav.some(r=>r.result!=='opened'))process.exitCode=1;console.log(JSON.stringify({probes:results.length,probeErrors:results.filter(r=>r.result==='probe-error').length,navigation:nav.length,navigationErrors:nav.filter(r=>r.result!=='opened').length}));
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
